#!/bin/bash
# Uninstall script for DuoConnect
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling DuoConnect..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping DuoConnect if running..."
pkill -f "DuoConnect" 2>/dev/null || true

# Unload service com.duo.connect.tcp
echo "Unloading service com.duo.connect.tcp..."
launchctl unload -w /Library/LaunchAgents/com.duo.connect.tcp.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.duo.connect.tcp.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.duo.connect.tcp.plist 2>/dev/null || true

# Unload service com.duo.connect.tcp.plist
echo "Unloading service com.duo.connect.tcp.plist..."
launchctl unload -w /Library/LaunchAgents/com.duo.connect.tcp.plist.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.duo.connect.tcp.plist.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.duo.connect.tcp.plist.plist 2>/dev/null || true

# Unload service com.duo.connect.tun
echo "Unloading service com.duo.connect.tun..."
launchctl unload -w /Library/LaunchAgents/com.duo.connect.tun.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.duo.connect.tun.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.duo.connect.tun.plist 2>/dev/null || true

# Unload service com.duo.connect.tun.plist
echo "Unloading service com.duo.connect.tun.plist..."
launchctl unload -w /Library/LaunchAgents/com.duo.connect.tun.plist.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.duo.connect.tun.plist.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.duo.connect.tun.plist.plist 2>/dev/null || true

# Remove $HOME/.duoconnect
echo "Removing $HOME/.duoconnect..."
if [ -d "$HOME/.duoconnect" ]; then
    rm -rf "$HOME/.duoconnect" 2>/dev/null || true
elif [ -f "$HOME/.duoconnect" ]; then
    rm -f "$HOME/.duoconnect" 2>/dev/null || true
fi

# Remove $HOME/Liibrary/Logs/Duo/Duoconnect
echo "Removing $HOME/Liibrary/Logs/Duo/Duoconnect..."
if [ -d "$HOME/Liibrary/Logs/Duo/Duoconnect" ]; then
    rm -rf "$HOME/Liibrary/Logs/Duo/Duoconnect" 2>/dev/null || true
elif [ -f "$HOME/Liibrary/Logs/Duo/Duoconnect" ]; then
    rm -f "$HOME/Liibrary/Logs/Duo/Duoconnect" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Duo
echo "Removing $HOME/Library/Logs/Duo..."
if [ -d "$HOME/Library/Logs/Duo" ]; then
    rm -rf "$HOME/Library/Logs/Duo" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Duo" ]; then
    rm -f "$HOME/Library/Logs/Duo" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
